// build.mjs: src/*.wgsl + the tables of x32.h -> ../x32w.ts
// node bend2/x32/build.mjs   (re-run after editing src/; x32w.ts is generated, do not edit it)
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
const here = path.dirname(new URL(import.meta.url).pathname);
const hfile = path.join(here, "x32.h");
const h = fs.readFileSync(hfile, "utf8");

function table(name) {
  const re = new RegExp(`x32_${name}\\[[^\\]]*\\](?:\\[[^\\]]*\\])?\\s*=\\s*\\{([\\s\\S]*?)\\};`);
  const m = h.match(re);
  if (!m) throw new Error("no table " + name);
  const body = m[1].replace(/\(x32_[a-z0-9]+\)/g, "").replace(/ull|u\b/g, "");
  return [...body.matchAll(/0x[0-9a-fA-F]+|\b\d+\b/g)].map((t) => BigInt(t[0]));
}
const hex = (v) => "0x" + v.toString(16).padStart(8, "0") + "u";
const u64 = (v) => `vec2<u32>(${hex(v >> 32n)}, ${hex(v & 0xffffffffn)})`;
const tables = {
  exp2j: () => { const t = table("exp2j"); return `const x32w_exp2j = array<vec2<u32>, ${t.length}>(\n  ${t.map(u64).join(",\n  ")});`; },
  expc: () => { const t = table("expc"); return `const x32w_expc = array<vec2<u32>, ${t.length}>(\n  ${t.map(u64).join(",\n  ")});`; },
  sinc: () => { const t = table("sinc"); return `const x32w_sinc = array<vec2<u32>, ${t.length}>(\n  ${t.map(u64).join(",\n  ")});`; },
  cosc: () => { const t = table("cosc"); return `const x32w_cosc = array<vec2<u32>, ${t.length}>(\n  ${t.map(u64).join(",\n  ")});`; },
  "2opi": () => { const t = table("2opi"); return `const x32w_2opi = array<u32, ${t.length}>(\n  ${t.map(hex).join(",\n  ")});`; },
  inv_odd: () => { const t = table("inv_odd"); return `const x32w_inv_odd = array<vec2<u32>, ${t.length}>(\n  ${t.map(u64).join(",\n  ")});`; },
  lnc: () => {
    const t = table("lnc"), rows = [];
    for (let i = 0; i < t.length; i += 2)
      rows.push(`vec4<u32>(${hex(t[i] >> 32n)}, ${hex(t[i] & 0xffffffffn)}, ${hex(t[i + 1] >> 32n)}, ${hex(t[i + 1] & 0xffffffffn)})`);
    return `const x32w_lnc = array<vec4<u32>, ${rows.length}>(\n  ${rows.join(",\n  ")});`;
  },
};
const counts = { exp2j: 64, expc: 7, sinc: 10, cosc: 10, "2opi": 12, inv_odd: 25, lnc: 130 };
for (const [k, n] of Object.entries(counts)) if (table(k).length !== n) throw new Error(`table ${k}: ${table(k).length} != ${n}`);

function block(file) {
  let s = fs.readFileSync(path.join(here, "src", file), "utf8");
  const m = s.match(/^\/\/TABLES (.*)\n/);
  if (m) s = s.slice(m[0].length) + "\n" + m[1].split(" ").map((k) => tables[k]()).join("\n\n") + "\n";
  if (/[^\x00-\x7f]/.test(s) || s.includes("@@")) throw new Error("non-ASCII or @@ in " + file);
  return s;
}
const blocks = [
  ["x32w_u64", [], "u64.wgsl"],
  ["x32_exp", ["x32w_u64"], "exp.wgsl"],
  ["x32_sincos", ["x32w_u64"], "sincos.wgsl"],
  ["x32_pow", ["x32w_u64", "x32_exp"], "pow.wgsl"],
  ["x32_softplus", ["x32w_u64", "x32_exp"], "softplus.wgsl"],
  ["x32_divsqrt", [], "divsqrt.wgsl"],
];
const hsha = crypto.createHash("sha256").update(h).digest("hex");
let out = `// x32w.ts: GENERATED by bend2/x32/build.mjs from bend2/x32/src/*.wgsl and the tables of bend2/x32/x32.h
// (sha256 ${hsha}). Do not edit; edit src/ and re-run \`node bend2/x32/build.mjs\`.
//
// WGSL ports of x32.h (u64 as vec2<u32>(hi, lo), integer-only) plus IEEE-exact div / sqrt.
// Public API (f32 in / out, bit-exact vs the C lane, NaN as one class):
//   x32_exp(x)      = (float)exp((double)x)
//   x32_sin(x), x32_cos(x) = (float)sin/cos((double)x)
//   x32_pow(x, y)   = (float)pow((double)x, (double)y)
//   x32_softplus(x) = ops.bend softplus1 = 20 < x ? x : (float)log(1.0 + exp((double)(x < 88 ? x : 88)))
//   x32_div(a, b)   = a / b (IEEE binary32, RNE, full domain)
//   x32_sqrt(v)     = sqrtf(v) (IEEE, full domain)
// Each also has a _bits(u32 ...) -> u32 form (x32w_exp_bits, x32w_sincos_bits(u, want_cos),
// x32w_pow_bits, x32w_softplus_bits, x32d_div_bits, x32d_sqrt_bits).
// Top-level names: x32_exp/x32_sin/x32_cos/x32_pow/x32_softplus/x32_div/x32_sqrt, x32w_*, x32d_*.
// None of wgsl.ts's old X32 runtime names other than x32_div / x32_sqrt / x32_exp are used; those three
// are replaced (old x32_exp was u32 -> i32: drop the old X32 section entirely).

export const X32W: Record<string, { deps: string[]; src: string }> = {\n`;
for (const [key, deps, file] of blocks)
  out += `  ${JSON.stringify(key)}: {\n    deps: ${JSON.stringify(deps)},\n    src: ${JSON.stringify(block(file))},\n  },\n`;
out += `};

// The WGSL for the given block keys and their deps, each once, deps first.
export function x32wSource(keys: string[]): string {
  const seen = new Set<string>(), parts: string[] = [];
  const add = (k: string) => {
    if (seen.has(k)) return;
    const b = X32W[k];
    if (!b) throw new Error("x32w: no block " + k);
    seen.add(k);
    for (const d of b.deps) add(d);
    parts.push(b.src);
  };
  for (const k of keys) add(k);
  return parts.join("\\n");
}
`;
fs.writeFileSync(path.join(here, "../x32w.ts"), out);
console.log("wrote x32w.ts", out.length, "bytes; x32.h sha256", hsha);
